"use client";

import { useEffect } from "react";
import styles from "./MenuOverlay.module.css";

const LINKS = [
  { href: "#treatments", label: "Behandlungen", index: "01" },
  { href: "#packages", label: "Pakete", index: "02" },
  { href: "#about", label: "Über uns", index: "03" },
  { href: "#cta", label: "Termin anfragen", index: "04" },
];

export default function MenuOverlay({
  open,
  onClose,
}: {
  open: boolean;
  onClose: () => void;
}) {
  useEffect(() => {
    document.body.style.overflow = open ? "hidden" : "";
    return () => {
      document.body.style.overflow = "";
    };
  }, [open]);

  return (
    <div
      className={`${styles.overlay} ${open ? styles.overlayOpen : ""}`}
      aria-hidden={!open}
    >
      <nav className={styles.links}>
        {LINKS.map((link, i) => (
          <a
            key={link.href}
            href={link.href}
            className={styles.link}
            style={{ transitionDelay: open ? `${0.08 * i + 0.15}s` : "0s" }}
            onClick={onClose}
          >
            <span className={styles.linkIndex}>{link.index}</span>
            <span className={styles.linkLabel}>{link.label}</span>
          </a>
        ))}
      </nav>

      <div className={styles.footer}>
        <span>Düsseldorf · Medienhafen</span>
        <a href="https://www.instagram.com/healthy_aesthetics_duesseldorf/">
          Instagram
        </a>
      </div>
    </div>
  );
}
